arguments.command:
curl -s -X POST "https://slack.com/api/conversations.list" -H "Authorization: Bearer <TOKEN>" --data-urlencode "token=<TOKEN>" --data-urlencode "exclude_archived=false" --data-urlencode "types=public_channel,private_channel" --data-urlencode "limit=1000" | python3 -c "
import json,sys
d=json.load(sys.stdin)
print('ok' if d.get('ok') else d)
if d.get('ok'):
    for key in ('channels','groups','private_channels'):
        for c in d.get(key,[]):
            print(key, c['id'], c['name'], 'archived' if c.get('is_archived') else '')
"

